from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    if row is None:
        return ""
    return row.get(column, "")


def _numeric(value: Any) -> Decimal:
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            return row.get(output_column, "")

    return ""


def _error(code: str, message: str) -> dict:
    return {"code": code, "message": message, "severity": "BLOCK"}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            disc_pct = _numeric(_value(record, "DISC_PCT"))
            if not (disc_pct >= Decimal("0") and disc_pct <= Decimal("100")):
                errors.append(_error("E5001", "Discount out of range"))

        if event == "UPDATE":
            disc_pct = _numeric(_value(record, "DISC_PCT"))
            owner_uid = _value(record, "OWNER_UID")
            role_for_mgr = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            role_for_admin = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if not (
                disc_pct > Decimal("20")
                and role_for_mgr != "MGR"
                and role_for_admin != "ADMIN"
            ):
                pass
            else:
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

            if (
                _value(old, "STAT_CD") == "I"
                and _value(record, "STAT_CD") != "I"
                and _value(record, "STAT_CD") != "X"
            ):
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_numeric(_value(record, "QTY")) > Decimal("0")):
                errors.append(_error("E5004", "Quantity must be positive"))

        if event == "INSERT":
            prod_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables, "PROD_MASTER", "PROD_ID", prod_id, "ACTIVE_FLG"
            )
            if active_flag != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
